export function useReadSession<
  TData = Awaited<ReturnType<typeof readSession>>,
  TError = ErrorType<ErrorEnvelope>,
>(
  id: string,
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof readSession>>, TError, TData>>;
    request?: SecondParameter<typeof axiosClient>;
  },
  queryClient?: QueryClient,
): UseQueryResult<TData, TError> & { queryKey: DataTag<QueryKey, TData, TError> } {
  const queryOptions = getReadSessionQueryOptions(id, options);

  const query = useQuery(queryOptions, queryClient) as UseQueryResult<TData, TError> & {
    queryKey: DataTag<QueryKey, TData, TError>;
  };

  return withQueryKey(query, queryOptions.queryKey);
}

/**
 * List Audit log entries, newest first, filtered by actor, action, target and time range, a page at a time. Requires an Admin whose auth session passed two-factor authentication.
 * @summary List Audit log
 */
export const listAuditEntries = (
  params?: ListAuditEntriesParams,
  options?: SecondParameter<typeof axiosClient>,
  signal?: AbortSignal,
) => {
  return axiosClient<AuditPage>(
    { url: `/api/admin/audit`, method: 'GET', params, signal },
    options,
  );
};

export const getListAuditEntriesQueryKey = (params?: ListAuditEntriesParams) => {
  return [`/api/admin/audit`, ...(params ? [params] : [])] as const;
};

export const getListAuditEntriesQueryOptions = <
  TData = Awaited<ReturnType<typeof listAuditEntries>>,
  TError = ErrorType<ErrorEnvelope>,
>(
  params?: ListAuditEntriesParams,
  options?: {
    query?: Partial<UseQueryOptions<Awaited<ReturnType<typeof listAuditEntries>>, TError, TData>>;
    request?: SecondParameter<typeof axiosClient>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getListAuditEntriesQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listAuditEntries>>> = ({ signal }) =>
    listAuditEntries(params, requestOptions, signal);

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof listAuditEntries>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

